import{_ as t,o as a,c as s,a2 as d}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Fidelity — dogfood-observability-dashboard (v1.17-2)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/observability/dashboard.md","filePath":"quality-reports/observability/dashboard.md"}'),r={name:"quality-reports/observability/dashboard.md"};function o(i,e,n,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="fidelity-—-dogfood-observability-dashboard-v1-17-2" tabindex="-1">Fidelity — dogfood-observability-dashboard (v1.17-2) <a class="header-anchor" href="#fidelity-—-dogfood-observability-dashboard-v1-17-2" aria-label="Permalink to &quot;Fidelity — dogfood-observability-dashboard (v1.17-2)&quot;">​</a></h1><p>Real-vs-mock behavioural fidelity for the Grafana-style observability dashboard dogfood, produced by <code>examples/dogfood-observability-dashboard/tests/emit-fidelity-report.test.ts</code>. Feeds <code>@kiwa-lab/quality-metrics</code> 7-axis release gate.</p><h2 id="baseline-real-mode-skipped-—-no-prometheus-url" tabindex="-1">Baseline (real mode skipped — no <code>PROMETHEUS_URL</code>) <a class="header-anchor" href="#baseline-real-mode-skipped-—-no-prometheus-url" aria-label="Permalink to &quot;Baseline (real mode skipped — no \`PROMETHEUS_URL\`)&quot;">​</a></h2><p>When the harness runs without a Prometheus URL, the real adapter emits <code>PROMETHEUS_ENV_MISSING</code> for every op. Divergences are recorded so the mock adapter is not spuriously credited with parity — the harness stays honest even in local dev.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider   : @kiwa-lab/observability/dashboard</span></span>
<span class="line"><span>version    : 2.0.0</span></span>
<span class="line"><span>verdict    : PASS</span></span>
<span class="line"><span>divergences: 2 (refreshDashboard / runQuery — recorded as BEHAVIORAL_DIVERGENCE, real mode absent)</span></span>
<span class="line"><span>axes       : 7 (common branch — dashboard is not a token-priced generative surface)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>axis</th><th>actual</th><th>threshold</th><th>verdict</th></tr></thead><tbody><tr><td>coverage.line</td><td>92.00%</td><td>85%</td><td>pass</td></tr><tr><td>coverage.branch</td><td>88.00%</td><td>80%</td><td>pass</td></tr><tr><td>coverage.function</td><td>95.00%</td><td>90%</td><td>pass</td></tr><tr><td>fidelity.ratio</td><td>100.00% (2/2)</td><td>70%</td><td>pass</td></tr><tr><td>perf.p95Ms</td><td>1.00 ms</td><td>100 ms</td><td>pass</td></tr><tr><td>mutation.killRate</td><td>70.00% (28/40)</td><td>60%</td><td>pass</td></tr><tr><td>testCount.behavior</td><td>18</td><td>10</td><td>pass</td></tr></tbody></table><p>The <code>divergences</code> count in the notes section counts every op whose mock path succeeded but whose real path threw <code>PROMETHEUS_ENV_MISSING</code> — this is expected in a real-mode-skipped baseline and does not itself fail the gate (fidelity ratio measures the mock-covered surface area, which is 100% for the 2 ops the AC scopes).</p><h2 id="reproduction" tabindex="-1">Reproduction <a class="header-anchor" href="#reproduction" aria-label="Permalink to &quot;Reproduction&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-observability-dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/dogfood-observability-dashboard/quality-report/fidelity-latest.md</span></span></code></pre></div><p>Live real-mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PROMETHEUS_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:9090</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-observability-dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>When the URL is set but a metric named <code>http.errors</code> / <code>http.requests</code> / <code>queue.depth</code> / <code>http.p99.latency.ms</code> is absent from the Prometheus target, the query returns an empty vector and the panel value collapses to 0. This is the same shape the mock returns when a metric name matches no records — mock / real behave identically for the empty-vector case.</p><h2 id="ops-under-measurement" tabindex="-1">Ops under measurement <a class="header-anchor" href="#ops-under-measurement" aria-label="Permalink to &quot;Ops under measurement&quot;">​</a></h2><p>Two provider-neutral ops on <code>DashboardAdapter</code> cover the Grafana dashboard difficulty surface end-to-end.</p><ul><li><code>runQuery</code> — execute a single PromQL-style query (metric name + aggregation + optional label filter) and return the aggregated numeric value + matched sample count</li><li><code>refreshDashboard</code> — re-evaluate every panel on the dashboard once, producing an ordered <code>PanelRenderResult[]</code> with value + chart_type + badge</li></ul><p>Plus accessors (<code>getRefreshCount</code> / <code>getPanel</code>) so Grafana-style refresh cadence assertions do not require wall-clock coupling.</p><h2 id="_5-panels-×-4-metric-queries" tabindex="-1">5 panels × 4 metric queries <a class="header-anchor" href="#_5-panels-×-4-metric-queries" aria-label="Permalink to &quot;5 panels × 4 metric queries&quot;">​</a></h2><p>The 5 seeded panels (<code>src/panels/index.ts</code>) each pin one chart_type against a shared query builder in <code>src/queries/index.ts</code>.</p><table tabindex="0"><thead><tr><th>panel id</th><th>chart_type</th><th>metric</th><th>aggregation</th><th>threshold</th></tr></thead><tbody><tr><td><code>panel-p99-latency-line</code></td><td>line</td><td><code>http.p99.latency.ms</code></td><td>max</td><td>≥ 300 critical / ≥ 200 warn</td></tr><tr><td><code>panel-request-count-bar</code></td><td>bar</td><td><code>http.requests</code></td><td>sum</td><td>none</td></tr><tr><td><code>panel-queue-depth-gauge</code></td><td>gauge</td><td><code>queue.depth</code></td><td>last</td><td>≥ 20 critical / ≥ 15 warn</td></tr><tr><td><code>panel-error-rate-stat</code></td><td>stat</td><td><code>http.errors</code></td><td>sum (status=500)</td><td>≥ 5 critical / ≥ 3 warn</td></tr><tr><td><code>panel-request-count-table</code></td><td>table</td><td><code>http.requests</code></td><td>count</td><td>none</td></tr></tbody></table><p><code>line</code> and <code>bar</code> both map to the observability package&#39;s <code>timeseries</code> PanelKind — the app-level chart_type is preserved as metadata on the render result so a Next.js App Router page can pick the correct chart component (v1.17-1 AC — 5 panel type 描画動作).</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Provider prefix <code>@kiwa-lab/observability/</code> triggers the common 7-axis branch of <code>evaluateReleaseGate</code> (<code>packages/quality-metrics/src/gate.ts</code>). The AI-LLM 4 axes (cost / latency / token / accuracy) do not apply because Prometheus is a metrics primitive, not a token-priced generative call. HTTP query round-trip latency feeds <code>perf.p95Ms</code> so dashboard performance stays visible in the report.</p><p><code>getRefreshCount</code> is deliberately NOT reset by <code>adapter.reset()</code> — the DashboardMock instance owns refresh identity across the adapter&#39;s lifetime, so tests can measure absolute refresh cadence without wall-clock coupling. <code>adapter.reset()</code> DOES clear traces, query counters, and latency samples so a test can start a fresh fidelity run without discarding refresh history.</p><p>The <code>line</code> and <code>bar</code> chart_types share the observability package&#39;s <code>timeseries</code> PanelKind. The distinction is a Grafana / Next.js rendering concern (line for a continuous trend, bar for a categorical bucket) and is preserved as <code>PanelRenderResult.chartType</code> metadata. A downstream <code>app/dashboard/page.tsx</code> server component picks the render component off <code>chartType</code> rather than <code>PanelKind</code> so both chart_types are visible end-to-end.</p>`,24)])])}const b=t(r,[["render",o]]);export{u as __pageData,b as default};
